{
  "name": "@ccx-agent/opencode-ccx",
  "version": "1.0.1",
  "description": "Production-grade prompt engineering for OpenCode — disciplined coding, risk-aware actions, adversarial verification",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm --external @opencode/plugin --external effect && tsc --emitDeclarationOnly",
    "clean": "rm -rf dist",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run clean && bun run build"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/Rejudge-F/ccx.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "claude",
    "agent",
    "harness",
    "prompt-engineering"
  ],
  "license": "MIT",
  "dependencies": {
    "bash-parser": "^0.5.0",
    "zod": "^4.1.8"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.2.5"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.5",
    "bun-types": "^1.3.11",
    "typescript": "^5.7.3"
  }
}
